//! Typed access to `tests/fixtures/vectors.json`, generated by `fixtures/gen/gen.mjs` from
//! independent JS implementations. Every test reads its fixtures through [`vectors`].
#![allow(dead_code)]

use serde::Deserialize;

#[derive(Debug, Deserialize)]
pub struct Programs {
    pub system: String,
    pub token: String,
    pub associated_token: String,
    pub metadata: String,
}

#[derive(Debug, Deserialize)]
pub struct SeedKey {
    pub seed_hex: String,
    pub pubkey: String,
}

#[derive(Debug, Deserialize)]
pub struct Keys {
    pub authority: SeedKey,
    pub owner: SeedKey,
    pub mint: SeedKey,
}

#[derive(Debug, Deserialize)]
pub struct OnCurve {
    pub pubkey: String,
    pub on_curve: bool,
}

#[derive(Debug, Deserialize)]
pub struct Ata {
    pub owner: String,
    pub mint: String,
    pub address: String,
    pub bump: u8,
}

#[derive(Debug, Deserialize)]
pub struct MetadataAddress {
    pub mint: String,
    pub address: String,
    pub bump: u8,
}

#[derive(Debug, Deserialize)]
pub struct MintTx {
    pub amount: u64,
    pub message_hex: String,
    pub signature: String,
    pub wire_hex: String,
}

#[derive(Debug, Deserialize)]
pub struct CreateMintTx {
    pub lamports: u64,
    pub message_hex: String,
    pub signatures: Vec<String>,
    pub wire_hex: String,
}

#[derive(Debug, Deserialize)]
pub struct IxAccount {
    pub pubkey: String,
    pub is_signer: bool,
    pub is_writable: bool,
}

#[derive(Debug, Deserialize)]
pub struct MetadataIx {
    pub program: String,
    pub accounts: Vec<IxAccount>,
    pub data_hex: String,
}

#[derive(Debug, Deserialize)]
pub struct Vectors {
    pub programs: Programs,
    pub keys: Keys,
    pub blockhash: String,
    pub on_curve: Vec<OnCurve>,
    pub ata: Ata,
    pub metadata_address: MetadataAddress,
    pub mint_tx: MintTx,
    pub create_mint_tx: CreateMintTx,
    pub metadata_create_ix: MetadataIx,
    pub metadata_update_ix: MetadataIx,
}

pub fn vectors() -> Vectors {
    const RAW: &str = include_str!("../fixtures/vectors.json");
    serde_json::from_str(RAW).expect("tests/fixtures/vectors.json matches Vectors")
}
